import{c as o,Q as a,j as l,m as t}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"别让 Claude Code 误删代码：这 5 层安全护栏必须配好","description":"","frontmatter":{},"headers":[],"relativePath":"research/tweets/2026-06-10-@vincemask-699973.md","filePath":"research/tweets/2026-06-10-@vincemask-699973.md","lastUpdated":1785909234000}'),i={name:"research/tweets/2026-06-10-@vincemask-699973.md"};function d(r,e,s,p,n,h){return a(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="别让-claude-code-误删代码-这-5-层安全护栏必须配好" tabindex="-1">别让 Claude Code 误删代码：这 5 层安全护栏必须配好 <a class="header-anchor" href="#别让-claude-code-误删代码-这-5-层安全护栏必须配好" aria-label="Permalink to &quot;别让 Claude Code 误删代码：这 5 层安全护栏必须配好&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/vincemask/status/2064581609928699973" target="_blank" rel="noreferrer">@vincemask</a>（Vince 聊开发）<br><strong>日期</strong>：2026-06-10<br><strong>類型</strong>：Twitter Article（簡體中文）<br><strong>統計</strong>：❤️ 28 · 🔁 4 · 👁 3027 · 🔖 24</p><hr><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>Claude Code 五層安全護欄（強→弱）：OS 沙箱+憑據隔離 → deny/ask/allow 原生權限（硬邊界）→ PreToolUse Hook（動態上下文判斷）→ 工程規則（CLAUDE.md/.claude/rules/）→ 遠端 CI+分支保護（最終兜底）；含 Codex 雙工具適配與命令風險分級（中文）。</p><hr><h2 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h2><ol><li>「只靠提示詞告訴它不要執行危險操作」遠遠不夠，需五層兜底</li><li>原生權限（deny/ask/allow）是真正硬邊界，優先於 Hook；Hook 適合動態上下文判斷</li><li>PreToolUse Hook matcher 必須覆蓋 Bash|Read|Edit|Write，只匹配 Bash 攔不住文件工具</li><li>Husky 可被繞過（--no-verify），必須配合遠端 CI + 分支保護做最終控制</li><li>Codex PreToolUse 支持 permissionDecision 但 &quot;ask&quot; 尚不支持，返回後會標記 Hook 失敗</li></ol><hr><h2 id="關鍵數據-工具-引用" tabindex="-1">關鍵數據 / 工具 / 引用 <a class="header-anchor" href="#關鍵數據-工具-引用" aria-label="Permalink to &quot;關鍵數據 / 工具 / 引用&quot;">​</a></h2><ul><li>五層架構：OS 沙箱 → deny/ask/allow → PreToolUse Hook → 工程規則 → 遠端門禁</li><li>六步起步順序：deny → ask → allow → Hook → rules → CI</li><li>Husky 繞過路徑：--no-verify / HUSKY=0 / -c core.hooksPath=/dev/null</li><li>Codex Hook 格式：permissionDecision (JSON) 或舊格式 decision:block</li><li>sandbox.filesystem 覆蓋所有子進程（kubectl/terraform/npm）</li></ul><hr><h2 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h2><ol><li>具體 deny/ask/allow 清單以圖片形式呈現（<code>[]</code> placeholder），需原文查閱</li><li>命令風險分級表格也在圖片中，文字版未完整列出</li><li>沙箱配置細節（sandbox.filesystem 實際設定方式）未在文字部分展示</li></ol><hr><h2 id="_5-維度評分" tabindex="-1">5 維度評分 <a class="header-anchor" href="#_5-維度評分" aria-label="Permalink to &quot;5 維度評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9</td><td>六步起步 + 具體配置 + Codex 適配</td></tr><tr><td>B. 創新性 (20%)</td><td>6</td><td>Claude Code 專項安全打包有價值</td></tr><tr><td>C. 證據品質 (20%)</td><td>7</td><td>具體 Hook exit code 行為 + Codex 相容說明</td></tr><tr><td>D. 技術深度 (15%)</td><td>8</td><td>五層分工 + matcher 修正 + 繞過路徑分析</td></tr><tr><td>E. 泛化性 (15%)</td><td>7</td><td>Claude Code/Codex 用戶適用</td></tr></tbody></table><p><strong>加權總分：7.55 → SKILL</strong></p><hr><h2 id="整合決策" tabindex="-1">整合決策 <a class="header-anchor" href="#整合決策" aria-label="Permalink to &quot;整合決策&quot;">​</a></h2><p><strong>SKILL</strong> — Claude Code 安全配置 SOP，可直接作為 security-hygiene SKILL 輸入材料</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Claude Code 一旦拿到文件修改、命令执行和 Git 操作权限，效率会大幅提升，风险也会同步放大。一条错误的 rm、一次误触发的数据库重置，或一次绕过检查的强制推送，都可能造成难以挽回的损失。</p><p>只靠提示词告诉它“不要执行危险操作”远远不够。真正可靠的方案，需要从执行环境、原生权限、动态 Hook、工程规则到远程仓库，建立一套层层兜底的安全机制。</p><p>本文将拆解 Claude Code 的 5 层安全护栏，并给出可直接落地的 deny、ask、allow 配置与命令分级清单，让 Agent 在安全边界内尽可能自主执行。</p><p>三层硬防线（沙箱 → 权限规则 → PreToolUse Hook），加两层软护栏（工程规则 → 远程门禁），以下从强到弱排列。</p><h2 id="第一层-os-沙箱与凭据隔离" tabindex="-1">第一层：OS 沙箱与凭据隔离 <a class="header-anchor" href="#第一层-os-沙箱与凭据隔离" aria-label="Permalink to &quot;第一层：OS 沙箱与凭据隔离&quot;">​</a></h2><p>最底层。限制文件系统、网络、密钥和执行环境。Claude Code 原生支持 sandbox.filesystem，作用于所有子进程（kubectl、terraform、npm 等），不是只拦 Claude 自己的工具调用。</p><p>这层搞定了，后面几层才有意义。</p><h2 id="第二层-原生权限规则-—-deny-ask-allow" tabindex="-1">第二层：原生权限规则 — deny / ask / allow <a class="header-anchor" href="#第二层-原生权限规则-—-deny-ask-allow" aria-label="Permalink to &quot;第二层：原生权限规则 — deny / ask / allow&quot;">​</a></h2><p>最可靠的命令控制层。Claude Code 原生权限系统，匹配顺序是 deny → ask → allow。</p><p>直接封死（deny）</p><p>需要确认（ask）</p><p>直接放行（allow）</p><p>原生权限是真正的硬边界，优先于 Hook。Hook 适合需要动态上下文判断的策略，不适合当唯一防线。</p><h2 id="第三层-pretooluse-hook-—-动态策略" tabindex="-1">第三层：PreToolUse Hook — 动态策略 <a class="header-anchor" href="#第三层-pretooluse-hook-—-动态策略" aria-label="Permalink to &quot;第三层：PreToolUse Hook — 动态策略&quot;">​</a></h2><p>原生权限处理「固定规则」，Hook 处理「要看上下文才知道」的判断——比如当前分支、目标 ref、命令参数组合。</p><p>脚本（共用核心）</p><p>关键修正：matcher 必须覆盖 Bash|Read|Edit|Write，只匹配 Bash 拦不住文件工具。</p><p>固定字符串匹配容易被绕过（rm -r -f /、git push -f、bash -c &#39;...&#39; 等）。Hook 是策略辅助，不是安全沙箱。强约束放原生 deny。</p><p>Claude Code 配置 — .claude/settings.json</p><blockquote><p>Claude Code 的 PreToolUse 支持通过 JSON 返回 permissionDecision: &quot;allow&quot; | &quot;deny&quot; | &quot;ask&quot;。exit code 2 等效 deny。ask 会弹出确认框。</p></blockquote><p>Codex 配置 — .codex/hooks.json</p><p>Codex 的 PreToolUse 支持通过 JSON 返回：</p><p>也兼容旧格式 <code>{&quot;decision&quot;: &quot;block&quot;, &quot;reason&quot;: &quot;...&quot;}</code>。exit code 2 同样生效。但 permissionDecision: &quot;ask&quot; 当前尚不支持——返回后会标记 Hook 失败并继续执行。</p><p>Hooks配置参考文章</p><h2 id="第四层-工程规则-—-claude-md-claude-rules" tabindex="-1">第四层：工程规则 — CLAUDE.md / .claude/rules/ <a class="header-anchor" href="#第四层-工程规则-—-claude-md-claude-rules" aria-label="Permalink to &quot;第四层：工程规则 — CLAUDE.md / .claude/rules/&quot;">​</a></h2><p>权限防灾难，规则防技术债。</p><p>.claude/rules/ 下每条一句：</p><p>示例：</p><ul><li><p>禁止内联 Validation Schema，统一放 types/ 目录</p></li><li><p>禁止跨 domain 建依赖</p></li><li><p>认证逻辑只读，不准重新设计</p></li><li><p>写新函数前先搜 shared packages</p></li><li><p>保护 .husky/ 和相关配置文件，不准改</p></li></ul><p>可参考文章</p><h2 id="第五层-远程门禁-—-ci-分支保护" tabindex="-1">第五层：远程门禁 — CI + 分支保护 <a class="header-anchor" href="#第五层-远程门禁-—-ci-分支保护" aria-label="Permalink to &quot;第五层：远程门禁 — CI + 分支保护&quot;">​</a></h2><p>本地 Hook 和 Agent 护栏只是第一道防线。下面这些才是最终控制点。</p><p>Husky（本地质量门禁，可绕过）</p><p>Husky 可以通过以下方式绕过：git commit --no-verify、git push --no-verify、HUSKY=0 git commit、git -c core.hooksPath=/dev/null commit。</p><p>所以必须配合：</p><ul><li><p>原生权限封禁 --no-verify 参数</p></li><li><p>远程 CI 重新跑 lint + test</p></li><li><p>分支保护要求 CI 必须通过</p></li></ul><p>远程仓库策略（不可绕过）</p><p>GitHub/GitLab branch protection:</p><ul><li>禁止 force push</li><li>要求 PR review</li><li>要求 CI status checks 通过</li><li>禁止直接 push main</li></ul><p>「feature 分支可以 push，main 不行」这条策略，靠的是远程分支保护规则，不是本地 Agent 配置。</p><h2 id="命令风险分级速查" tabindex="-1">命令风险分级速查 <a class="header-anchor" href="#命令风险分级速查" aria-label="Permalink to &quot;命令风险分级速查&quot;">​</a></h2><p>git add 修改 index、git checkout -b 创建分支、gh pr create 创建远程 PR——都不是只读操作，不能放进无脑放行清单。</p><h2 id="双工具适配-claude-code-codex-共用" tabindex="-1">双工具适配：Claude Code + Codex 共用 <a class="header-anchor" href="#双工具适配-claude-code-codex-共用" aria-label="Permalink to &quot;双工具适配：Claude Code + Codex 共用&quot;">​</a></h2><p>Bash 命令检测的核心脚本可以复用。两边 PreToolUse Command Hook 都从 stdin 收 JSON，exit code 2 都能阻止调用。</p><p>落地建议</p><p>Deny List 和 Allow List 保持一致，但分别维护薄适配层。不要假设两边所有 Hook 事件和决策字段长期保持完全兼容。</p><h2 id="怎么起步" tabindex="-1">怎么起步 <a class="header-anchor" href="#怎么起步" aria-label="Permalink to &quot;怎么起步&quot;">​</a></h2><ol><li><p>先配原生 permissions.deny，覆盖最危险的操作</p></li><li><p>加 permissions.ask，覆盖需要确认的远程副作用操作</p></li><li><p>加 permissions.allow，放行只读和本地可逆操作</p></li><li><p>用 PreToolUse Hook 补动态判断（分支检测、参数组合等）</p></li><li><p>工程规则放 CLAUDE.md / rules</p></li><li><p>远程 CI 和分支保护做最终兜底</p></li></ol><h2 id="更多文章推荐阅读" tabindex="-1">更多文章推荐阅读 <a class="header-anchor" href="#更多文章推荐阅读" aria-label="Permalink to &quot;更多文章推荐阅读&quot;">​</a></h2><ol><li><p>Claude Code 高阶用法：10 个插件搭起完整开发工作流</p></li><li><p>如何用 5 个工具 + 自定义 Hooks 把 Claude Code Token 消耗砍掉 90%+</p></li><li><p>Antigravity CLI 入门指南：从安装到第一次运行</p></li><li><p>claude-code-setup 插件实战指南：让 Claude Code 真正读懂你的项目</p></li><li><p>Claude Code 工程化指南：高效组织 .claude/ 目录</p></li><li><p>Claude Code 斜杠命令全解：14 条实用指南</p></li><li><p>从 0 开始：用 Hooks 打造自动化 Claude Code 工作流</p></li><li><p>写好 CLAUDE.md 的 8 条经验：让 Claude Code 更懂你的项目</p></li><li><p>Claude Code 项目的 MEMORY.md 使用指南</p></li></ol>',73)])])}const k=o(i,[["render",d]]);export{c as __pageData,k as default};
